export type DSAbilityRoll = "Might" | "Agility" | "Reason" | "Intuition" | "Presence";

export interface DSAbility {
  id: string;
  name: string;
  classId: string;          // one of the 9 class ids, or "common" for shared combat abilities
  level: number | null;     // null for common/level-less abilities
  subclass: string | null;  // subclass tag when the ability is gated to one
  signature: boolean;       // at-will signature ability
  free: boolean;            // free strike
  action: string | null;    // "Main action" | "Maneuver" | "Triggered" | ...
  costResource: string | null;  // heroic resource spent, if any (Ferocity, Piety, ...)
  costAmount: number | null;
  distance: string | null;
  target: string | null;
  keywords: string[];
  roll: DSAbilityRoll | null;   // characteristic the power roll adds, if it is a power-roll ability
}

