export function abilitiesForClass(classId: string, maxLevel = 10): DSAbility[] {
  return DS_ABILITIES
    .filter((a) => a.classId === classId && (a.level == null || a.level <= maxLevel))
    .sort((a, b) => (a.level ?? 0) - (b.level ?? 0)
      || Number(b.signature) - Number(a.signature)
      || a.name.localeCompare(b.name));
}

export const commonAbilities = (): DSAbility[] => DS_ABILITIES.filter((a) => a.classId === "common");

export const abilityById = (id: string): DSAbility | undefined =>
  DS_ABILITIES.find((a) => a.id === id);

// A one-line explainer generated from the ability's MECHANICS - never MCDM's effect text.
export function abilityExplainer(a: DSAbility): string {
  const parts: string[] = [];
  if (a.signature) parts.push("Signature (at-will)");
  else if (a.free) parts.push("Free strike");
  else if (a.costResource) parts.push(`Heroic - ${a.costAmount ?? ""} ${a.costResource}`.trim());
  if (a.action) parts.push(a.action);
  if (a.keywords.length) parts.push(a.keywords.join(", "));
  if (a.distance) parts.push(a.distance);
  if (a.target) parts.push(a.target);
  if (a.roll) parts.push(`power roll + ${a.roll}`);
  return parts.join(" · ");
}
